async function loadDeviceSettings(){try{const e=await fetch("/api/settings/device");if(e.ok){const t=await e.json();document.getElementById("device-name").value=t.name||"",document.getElementById("wled-activate").checked=t.wled,document.getElementById("wled-count").value=t.count||"",document.getElementById("wled-order").value=t.order||"",document.getElementById("analog-activate").checked=t.analog,document.getElementById("analog-mode").value=t.mode||"",document.getElementById("switch-activate").checked=t.switch,document.getElementById("switch-action").value=t.action||"",document.getElementById("debug-log-activate").checked=t.logging,toggleSection("wled-activate",".wled-settings"),toggleSection("analog-activate",".analog-settings"),toggleSection("switch-activate",".switch-settings")}else console.error("Failed to load device settings")}catch(e){console.error("Error fetching device settings:",e)}}async function saveDeviceSettings(){const e=document.getElementById("device-name").value,t=document.getElementById("wled-activate").checked,n=document.getElementById("wled-count").value,o=document.getElementById("wled-order").value,c=document.getElementById("analog-activate").checked,d=document.getElementById("analog-mode").value,a=document.getElementById("switch-activate").checked,l=document.getElementById("switch-action").value,i=document.getElementById("debug-log-activate").checked,s=new URLSearchParams;s.append("name",e),s.append("wled",t),s.append("count",n),s.append("order",o),s.append("analog",c),s.append("mode",d),s.append("switch",a),s.append("action",l),s.append("logging",i);try{if((await fetch("/api/settings/device",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:s.toString()})).ok){const e=document.getElementById("alert-saved-device");e.style.display="block",setTimeout((()=>{e.style.display="none"}),3e3)}else console.error("Failed to save device settings")}catch(e){console.error("Error saving device settings:",e)}}function scrollToTop(){window.scrollTo({top:0,behavior:"smooth"})}function toggleSection(e,t){const n=document.getElementById(e),o=document.querySelector(t);n.checked?o.style.display="block":o.style.display="none",n.addEventListener("change",(function(){this.checked?o.style.display="block":o.style.display="none"}))}document.getElementById("btn-save-device").addEventListener("click",(function(e){e.preventDefault(),saveDeviceSettings()})),document.getElementById("btn-reset").addEventListener("click",(function(){new bootstrap.Modal(document.getElementById("modal-reset")).show()})),document.getElementById("btn-reset-modal").addEventListener("click",(async function(){try{if((await fetch("/api/reset",{method:"POST"})).ok){bootstrap.Modal.getInstance(document.getElementById("modal-reset")).hide(),window.location.replace("/")}else console.error("Failed to save device settings")}catch(e){console.error("Error saving device settings:",e)}})),document.getElementById("btn-modal-close").addEventListener("click",(function(){bootstrap.Modal.getInstance(document.getElementById("modal-reset")).hide()})),window.onload=function(){loadDeviceSettings(),document.getElementById("alert-saved-device").style.display="none"};